var plugins =
  new Dictionary<string, IExporter>();
void Registriere(IExporter p)
  => plugins[p.Name] = p;

Registriere(new CsvExporter());
var daten =
  new List<Eintrag> { new("Lena", 1) };
foreach (var (name, p) in plugins)
  Console.WriteLine(
    $"{name} -> {p.Export(daten)}");
// csv -> Lena;1


public interface IExporter
{
  string Name { get; }
  string Export(IReadOnlyList<Eintrag> d);
}
public record Eintrag(string Name, int Note);

public class CsvExporter : IExporter
{
  public string Name => "csv";
  public string Export(IReadOnlyList<Eintrag> d)
    => string.Join("\n",
         d.Select(e => $"{e.Name};{e.Note}"));
}

using System.Reflection;

var plugins = new List<IExporter>();
var ordner = Path.Combine(
  AppContext.BaseDirectory, "plugins");
foreach (var dll in Directory.GetFiles(
           ordner, "*.dll"))
{
  var asm = Assembly.LoadFrom(dll);
  foreach (var typ in asm.GetTypes())
    if (typeof(IExporter)
          .IsAssignableFrom(typ)
        && !typ.IsAbstract)
      plugins.Add((IExporter)
        Activator.CreateInstance(typ)!);
}
foreach (var p in plugins)
  Console.WriteLine(
    $"{p.Name} -> " +
    p.Export([new("Lena", 1)]));
// pdf -> PDF mit 1 Zeilen

public interface IVersand
{
  void Senden(string an, string text);
}

public class Zeugnisdienst(
  IExporter exporter, IVersand versand)
{
  public void Sende(
    IReadOnlyList<Eintrag> daten, string an)
    => versand.Senden(an,
         exporter.Export(daten));
}

// Im Test: Fake statt Mailserver
public class FakeVersand : IVersand
{
  public List<string> Gesendet { get; } = [];
  public void Senden(string an, string text)
    => Gesendet.Add($"{an}: {text}");
}

using Microsoft.Extensions.DependencyInjection;

var services = new ServiceCollection();
services.AddSingleton<IExporter, CsvExporter>();
services.AddSingleton<IVersand, FakeVersand>();
services.AddTransient<Zeugnisdienst>();

using var sp = services.BuildServiceProvider();
var dienst = sp
  .GetRequiredService<Zeugnisdienst>();
dienst.Sende([new("Lena", 1)], "eltern@x.at");
var fake = (FakeVersand)sp
  .GetRequiredService<IVersand>();
Console.WriteLine(fake.Gesendet[0]);
// eltern@x.at: Lena;1

